/*
 * A032928  Numbers whose set of base-7 digits is {1,2}.
 * https://oeis.org/A032928
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n-th positive integer whose base‑7 representation
 *            uses only the digits 1 and 2. The sequence is generated by
 *            taking the binary representation of (n‑1) offset by the
 *            cumulative counts of shorter digit‑lengths and mapping 0→1 and
 *            1→2
 * Range:     u8 n <= 14, u16 n <= 126, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* n is guaranteed ≥ 1 in the OEIS offset; if n == 0 we return 0. */
    if (n == (idx_t)0)
        return (seq_t)0;

    /* 2^k : number of terms of length k */
    idx_t pow2 = (idx_t)2; /* 2^1 */
    idx_t k    = 1;        /* current length of digits */

    /* Find minimal k such that 2^{k+1} - 2 ≥ n, i.e.
       (pow2 << 1) - 2 ≥ n. */
    while (((pow2 << 1) - (idx_t)2) < n) {
        pow2 <<= 1; /* now 2^{k+1} */
        ++k;
    }

    /* Index within the block of length k (0‑based) */
    idx_t r = n - pow2 + (idx_t)1;  /* r < pow2 */

    /* Build the base‑7 number using digits 1 for bit 0 and 2 for bit 1. */
    seq_t res = (seq_t)0;
    for (idx_t j = k; j-- > 0; ) {
        seq_t digit = ((r >> j) & (idx_t)1) ? (seq_t)2 : (seq_t)1;
        res = res * (seq_t)7 + digit;
    }
    return res;
}
